var velen = context.rulePiece;
if (!velen || velen.currentHp <= 0 || context.playerId !== velen.ownerPlayerId) return { success: false, message: '' };
var turnNumber = battle.turn && battle.turn.turnNumber ? battle.turn.turnNumber : 0;
var player = battle.players.find(function(item) { return item.playerId === velen.ownerPlayerId; }); var completed = 0;
if (player && player.hand) player.hand.forEach(function(card) { var prophecy = card.holyProphecy; if (!prophecy || prophecy.sourcePieceId !== velen.instanceId || prophecy.createdTurnNumber >= turnNumber) return; card.holyProphecyEnhanced = true; delete card.holyProphecy; completed++; });
var sheltered = [];
battle.pieces.slice().forEach(function(target) {
  if (target.currentHp <= 0 || target.ownerPlayerId !== velen.ownerPlayerId) return;
  var tag = target.statusTags && target.statusTags.find(function(item) { return item.type === 'velen-fate-shelter' && item.sourceId === velen.instanceId && item.createdTurnNumber < turnNumber; });
  if (!tag) return;
  healDamage(velen, target, 8, battle, 'velen-fate-shelter');
  var shield = target.statusTags && target.statusTags.find(function(item) { return item.type === 'divine-shield'; });
  if (!shield) { addStatusEffectById(target.instanceId, { id: 'divine-shield', name: '圣盾', type: 'divine-shield', currentDuration: -1, currentUses: -1, intensity: 1, stacks: 1, relatedRules: ['rule-divine-shield'] }); addRuleById(target.instanceId, 'rule-divine-shield'); }
  removeStatusEffectById(target.instanceId, tag.id); removeRuleById(target.instanceId, 'rule-velen-fate-target'); sheltered.push(target.name || target.templateId);
});
if (completed === 0 && sheltered.length === 0) return { success: false, message: '' };
var messages = []; if (completed > 0) messages.push(completed + '张圣光手牌完成预言'); if (sheltered.length > 0) messages.push(sheltered.join('、') + '完成命运庇护');
return { success: true, message: velen.name + '：' + messages.join('；') };
